package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;import java.util.*;
/** Registry for executable supplement procedures. A rule becomes executable only after an exact, sourced procedure is registered. */
public final class AuthorizedRuleProcedureEngine{
 private AuthorizedRuleProcedureEngine(){} private static final Map<String,JSONObject> REG=new LinkedHashMap<>();
 public static synchronized JSONObject register(JSONObject raw){JSONObject r=copy(raw);validate(r);String id=r.optString("id").trim();REG.put(id,r);return copy(r);}
 public static synchronized boolean has(String id){return id!=null&&REG.containsKey(id.trim());}
 public static synchronized JSONObject get(String id){return copy(id==null?null:REG.get(id.trim()));}
 public static synchronized JSONArray ids(){JSONArray a=new JSONArray();for(String id:REG.keySet())a.put(id);return a;}
 public static JSONObject gate(String id,JSONObject inputs){JSONObject o=new JSONObject();try{JSONObject r=get(id);boolean known=r.length()>0;JSONArray missing=new JSONArray();if(known){JSONArray req=r.optJSONArray("required_inputs");if(req!=null)for(int i=0;i<req.length();i++){String k=req.optString(i);if(inputs==null||!inputs.has(k))missing.put(k);}}String procedureType=known?r.optString("procedure_type","").trim():"";boolean manual=known&&"state_rule_gate".equalsIgnoreCase(procedureType);boolean ok=known&&!manual&&missing.length()==0;String authority=ok?"authorized_compiled_procedure":(manual?"registered_requires_manual_resolution":"blocked");o.put("rule_id",id==null?"":id).put("registered",known).put("inputs_complete",missing.length()==0).put("executable",ok).put("requires_manual_resolution",manual).put("procedure_type",procedureType).put("missing_inputs",missing).put("authority",authority);if(known)o.put("source_book",r.optString("source_book")).put("source_locator",r.optString("source_locator"));}catch(Exception ignored){}return o;}
 private static void validate(JSONObject r){if(r==null)throw new IllegalArgumentException("regra ausente");if(r.optString("id").trim().length()<4)throw new IllegalArgumentException("rule id inválido");if(r.optString("domain").trim().isEmpty())throw new IllegalArgumentException("domínio obrigatório");if(r.optString("source_book").trim().isEmpty())throw new IllegalArgumentException("fonte obrigatória");if(r.optString("source_locator").trim().isEmpty())throw new IllegalArgumentException("localizador da fonte obrigatório");if(r.optString("procedure_type").trim().isEmpty())throw new IllegalArgumentException("procedure_type obrigatório");if(r.optJSONArray("required_inputs")==null)throw new IllegalArgumentException("required_inputs obrigatório");}
 private static JSONObject copy(JSONObject o){JSONObject c=new JSONObject();if(o==null)return c;try{java.util.Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();c.put(k,o.opt(k));}}catch(Exception ignored){}return c;}
}
